<?php
/** Sincronizador esportivo Akira com adaptadores: generic, api_football, football_data. */
require_once __DIR__ . '/../bootstrap.php';
$s=current_settings();$url=trim((string)($s['sports_api_url']??''));$key=decrypt_secret((string)($s['sports_api_key_enc']??''));$provider=(string)($s['sports_provider']??'generic');$date=$argv[1]??date('Y-m-d');
if($url===''){fwrite(STDERR,"sports_api_url não configurada\n");exit(2);} $headers=["Accept: application/json"];$endpoint=$url;
if($provider==='api_football'){$sep=str_contains($url,'?')?'&':'?';$endpoint=$url.$sep.'date='.rawurlencode($date);if($key!=='')$headers[]='x-apisports-key: '.$key;}
elseif($provider==='football_data'){$sep=str_contains($url,'?')?'&':'?';$endpoint=$url.$sep.'dateFrom='.rawurlencode($date).'&dateTo='.rawurlencode($date);if($key!=='')$headers[]='X-Auth-Token: '.$key;}
else{$sep=str_contains($url,'?')?'&':'?';$endpoint=$url.$sep.'date='.rawurlencode($date);if($key!=='')$headers[]='Authorization: Bearer '.$key;}
$opts=['http'=>['method'=>'GET','timeout'=>25,'header'=>implode("\r\n",$headers)."\r\n"]];$raw=@file_get_contents($endpoint,false,stream_context_create($opts));if($raw===false){fwrite(STDERR,"Falha ao consultar provedor esportivo\n");exit(3);} $data=json_decode($raw,true);$games=[];
if($provider==='api_football'&&is_array($data['response']??null))foreach($data['response'] as $r){$fixture=$r['fixture']??[];$league=$r['league']??[];$teams=$r['teams']??[];$goals=$r['goals']??[];$games[]=['id'=>(string)($fixture['id']??''),'starts_at'=>date('Y-m-d H:i:s',strtotime((string)($fixture['date']??''))),'competition'=>(string)($league['name']??''),'home_team'=>(string)($teams['home']['name']??''),'away_team'=>(string)($teams['away']['name']??''),'home_score'=>$goals['home']??null,'away_score'=>$goals['away']??null,'status'=>map_status((string)($fixture['status']['short']??'')),'channel_keywords'=>'','stream_id'=>''];}
elseif($provider==='football_data'&&is_array($data['matches']??null))foreach($data['matches'] as $r){$score=$r['score']['fullTime']??[];$games[]=['id'=>(string)($r['id']??''),'starts_at'=>date('Y-m-d H:i:s',strtotime((string)($r['utcDate']??''))),'competition'=>(string)($r['competition']['name']??''),'home_team'=>(string)($r['homeTeam']['name']??''),'away_team'=>(string)($r['awayTeam']['name']??''),'home_score'=>$score['home']??null,'away_score'=>$score['away']??null,'status'=>map_status((string)($r['status']??'')),'channel_keywords'=>'','stream_id'=>''];}
else $games=is_array($data)&&isset($data['games'])&&is_array($data['games'])?$data['games']:[];
$pdo=db();$sql='INSERT INTO games(external_id,starts_at,competition,home_team,away_team,home_score,away_score,status,channel_keywords,stream_id,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,CURRENT_TIMESTAMP) ON CONFLICT(external_id) WHERE external_id <> \'\' DO UPDATE SET starts_at=excluded.starts_at,competition=excluded.competition,home_team=excluded.home_team,away_team=excluded.away_team,home_score=excluded.home_score,away_score=excluded.away_score,status=excluded.status,channel_keywords=CASE WHEN excluded.channel_keywords<>\'\' THEN excluded.channel_keywords ELSE games.channel_keywords END,stream_id=CASE WHEN excluded.stream_id<>\'\' THEN excluded.stream_id ELSE games.stream_id END,updated_at=CURRENT_TIMESTAMP';$st=$pdo->prepare($sql);$count=0;
foreach($games as $g){$external=trim((string)($g['id']??''));if($external===''||empty($g['starts_at'])||empty($g['home_team'])||empty($g['away_team']))continue;$st->execute([$external,(string)$g['starts_at'],(string)($g['competition']??''),(string)$g['home_team'],(string)$g['away_team'],$g['home_score']??null,$g['away_score']??null,(string)($g['status']??'scheduled'),(string)($g['channel_keywords']??''),(string)($g['stream_id']??'')]);$count++;}
echo "Provedor: {$provider} • Sincronizados: {$count}\n";
function map_status(string $s):string{$u=strtoupper($s);if(in_array($u,['1H','2H','HT','ET','LIVE','IN_PLAY','PAUSED'],true))return 'live';if(in_array($u,['FT','AET','PEN','FINISHED'],true))return 'finished';return 'scheduled';}
